function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;}}
var PREFIX="JAH-TMFE-";
var DBTITLE="AI Frontend Development Signature Database";
var DESC="Everything an AI needs to build real website frontends: components, state management, styling systems, routing, and performance \u2014 each record a complete working technique with runnable code, the trade-offs explained honestly, and the production pitfalls called out before they bite.";
var CATS=["components", "state-management", "styling-systems", "routing", "performance"];
