var SRC_DETAIL="Signature-developed original content; speculative or forward-looking guidance is labeled Signature-generated, never presented as established public record.";
var REQUIRED=["name","how_it_works","key_points","requirements","standards","citations"];
var DATA=[{"t": "Component Anatomy (Props, State, Effects)", "cat": "components", "d": "A component is a function of props and state that returns UI, with effects for side work. The anatomy that scales: props typed and documented, internal state minimal (derived values computed, not stored), effects with cleanup, and composition over configuration. The classic AI mistake is components that fetch, format, and render — split those into a data hook, a pure formatter, and a presentational component. Each piece becomes testable and reusable.", "h": "Define the component's props interface first, keep state to what the user can change, compute everything derivable, isolate side effects in hooks with cleanup functions, then write one test rendering with sample props and one testing the hook in isolation.", "k": ["Props in, UI out — side effects live in hooks.", "Derived values are computed, never stored as state.", "Effects always clean up (subscriptions, timers, listeners).", "Split fetch/format/render into three units."], "r": ["A component framework (React/Vue/Svelte).", "TypeScript or prop types for the props contract.", "A test renderer."], "s": ["No fetching inside presentational components.", "All effects have cleanup paths."], "c": ["React docs: components — react.dev/learn", "Vue components — vuejs.org/guide/essentials/component-basics"], "sig": "Signature rule: Signature components declare their data dependencies as props — a component that secretly fetches is a reviewed finding.", "demo": "function UserCard({user,onSelect}){\n  // pure presentational: props in, UI out\n  return `<article><h2>${user.name}</h2><button data-id=\"${user.id}\">Select</button></article>`;\n}\nfunction useUsers(){\n  // data hook: fetching isolated here\n  return {users:[{id:1,name:'Ada'},{id:2,name:'Grace'}],loading:false};\n}\nconst {users}=useUsers();\nconsole.log(UserCard({users:users[0]}));\nconsole.log('rendered',users.length,'users, component stayed pure');"}, {"t": "Compound Components Pattern", "cat": "components", "d": "Compound components share implicit state through context: <Tabs><TabList><Tab/><TabList/><TabPanels><TabPanel/>... — the parent owns the active tab, children coordinate without prop drilling. This pattern produces flexible, accessible APIs: users compose the pieces, the component manages the wiring. Implementation is React context (or provide/inject in Vue) holding state plus a registration mechanism for children. AI-generated component libraries should reach for this pattern whenever pieces must coordinate but stay composable.", "h": "Create a context holding the shared state, build the parent that provides it, build children that consume it (and register themselves if order matters), add keyboard navigation at the parent level, then compose a demo using only the public pieces.", "k": ["Parent owns state; children coordinate via context.", "Users compose pieces; the component handles wiring.", "Keyboard behavior lives at the parent level.", "Registration lets children participate in ordering."], "r": ["Context API of your framework.", "An accessibility checklist (ARIA roles).", "Keyboard event handling."], "s": ["ARIA roles correct for the pattern (tablist/tab/tabpanel).", "Full keyboard operability."], "c": ["Compound components — kentcdodds.com/blog/compound-components", "Reach UI patterns — reach.tech"], "sig": "Signature rule: Signature compound components ship an a11y test asserting roles and keyboard flow — coordination without accessibility is incomplete.", "demo": "// compound Tabs sketch (framework-agnostic logic)\nfunction createTabs(){\n  const tabs=[]; let active=0;\n  return {\n    register(label){tabs.push(label);},\n    select(i){active=i;},\n    render(){return tabs.map((t,i)=>`${i===active?'▶':' '} ${t}`).join('\\n');}\n  };\n}\nconst t=createTabs(); t.register('Home'); t.register('About'); t.select(1);\nconsole.log(t.render());"}, {"t": "Render Props and Headless Components", "cat": "components", "d": "Headless components provide behavior with zero styling: a render prop or slot receives state and handlers, and the consumer renders whatever markup they want. This separates logic (keyboard nav, selection state, async status) from presentation completely — one headless Listbox powers ten different designs. Libraries like Headless UI and Radix prove the model. AI UI generation loves headless components because the AI can invent any visual design while the tricky interaction logic stays battle-tested.", "h": "Build the headless component owning state and keyboard logic, expose state/handlers via render prop or scoped slot, write one consumer with a plain design and one with a fancy design sharing the same headless core, then test keyboard interaction once — both designs inherit it.", "k": ["Behavior in the headless core; visuals in the consumer.", "One keyboard implementation serves every design.", "Render props (or slots) are the handoff mechanism.", "Test interaction once, reuse across designs."], "r": ["A headless library or your own render-prop component.", "Two visual designs to prove separation.", "Keyboard interaction tests."], "s": ["Headless core has no visual opinions (no class names).", "Accessibility handled in the core, not left to consumers."], "c": ["Headless UI — headlessui.com", "Radix primitives — radix-ui.com/primitives"], "sig": "Signature rule: Signature headless components document their keyboard map in the README — invisible behavior must be discoverable.", "demo": "// headless toggle: logic only, consumer renders\nfunction createToggle(initial){\n  let on=initial; const subs=[];\n  return {\n    get state(){return {on, toggle:()=>{on=!on; subs.forEach(f=>f(on));}};},\n    subscribe(f){subs.push(f);}\n  };\n}\nconst t=createToggle(false);\nconst s1=t.state; s1.toggle();\nconsole.log('toggled:',t.state.on);\nconsole.log('consumer renders whatever it wants from {on,toggle}');"}, {"t": "Error Boundaries and Fallback UI", "cat": "components", "d": "Error boundaries catch rendering crashes and show fallback UI instead of a white screen: class components with componentDidCatch in React, onErrorCaptured in Vue, or framework-agnostic window.onerror for the last resort. Place boundaries at strategic levels — per-widget, not just at the root — so one crashing widget doesn't kill the page. Log the error with component stack to your error service, offer a retry button that resets the boundary, and never swallow errors silently in production.", "h": "Add an error boundary component with fallback UI and retry, wrap each independent widget (not just the app root), wire the catch to log component stacks to your error tracker, simulate a crash in one widget, and verify the rest of the page survives and retry recovers.", "k": ["Boundaries per widget — one crash shouldn't kill the page.", "Fallback UI always offers retry.", "Log component stacks, not just messages.", "Never silently swallow — log everything."], "r": ["An error tracking service.", "A retry/reset mechanism.", "A way to simulate crashes in dev."], "s": ["Production never shows a white screen or raw stack.", "Errors logged with enough context to reproduce."], "c": ["React error boundaries — react.dev/reference/react/Component#catching-rendering-errors", "Sentry frontend — docs.sentry.io/platforms/javascript"], "sig": "Signature rule: Signature boundaries record the user's last three actions before the crash — reproduction steps captured automatically.", "demo": "// error boundary logic sketch\nfunction withBoundary(render, fallback){\n  return (...args)=>{\n    try{return render(...args);}\n    catch(e){console.error('boundary caught:',e.message);return fallback(e);}\n  };\n}\nconst risky=withBoundary(\n  ()=>{throw new Error('widget exploded');},\n  (e)=>`<div class=\"error\">Something broke. <button>Retry</button> (${e.message})</div>`);\nconsole.log(risky());\nconsole.log('page survived: other widgets unaffected');"}, {"t": "Portals and Layered UI (Modals, Toasts)", "cat": "components", "d": "Portals render UI outside the component's DOM position — modals, toasts, and dropdowns portal to document.body to escape overflow:hidden and z-index traps. A modal needs: focus trap (tab cycles inside), Escape to close, click-outside to close (optional), aria-modal, and returning focus to the trigger on close. Toasts need a queue with auto-dismiss and pause-on-hover. AI-generated modals commonly forget focus management — that's the difference between a demo and a product.", "h": "Build a Portal helper targeting document.body, implement Modal with focus trap + Escape + focus return, implement a toast queue with auto-dismiss, test with keyboard only (tab should never leave the modal), then verify screen reader announces the modal.", "k": ["Portal to body — escape overflow and z-index traps.", "Focus trap + Escape + focus return are mandatory.", "Toasts queue; auto-dismiss pauses on hover.", "aria-modal and roles announced to screen readers."], "r": ["A portal mechanism (createPortal / Teleport).", "Focus trap utility.", "A toast queue store."], "s": ["Keyboard users fully operate modals and dismiss toasts.", "Focus returns to the trigger element on close."], "c": ["Radix dialog — radix-ui.com/primitives/docs/components/dialog", "WAI-ARIA dialog pattern — w3.org/WAI/ARIA/apg/patterns/dialog-modal"], "sig": "Signature rule: Signature modals assert in tests that focus never escapes — the trap is proven, not assumed.", "demo": "// focus trap logic sketch\nfunction trapFocus(container){\n  const els=container.querySelectorAll('button,[href],input');\n  const list=[...els];\n  return (e)=>{\n    if(e.key!=='Tab')return;\n    const first=list[0],last=list[list.length-1];\n    if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}\n    else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}\n  };\n}\nconsole.log('trap: Tab cycles within', 'button,[href],input','set; Escape closes; focus returns to trigger');"}, {"t": "Virtualized Lists for Big Data", "cat": "components", "d": "Virtualization renders only visible rows: a 100,000-row list mounts ~30 DOM nodes, recycling them as you scroll. Libraries (react-window, virtuoso) compute which slice is visible from scroll position and row heights. Use it when lists exceed a few hundred rows or rows are expensive. Fixed heights are simple; dynamic heights need measurement. AI-generated admin tools and data browsers need this the moment real data arrives — rendering 10k rows naively freezes the page.", "h": "Pick a virtualization library, define row height (fixed) or a measurement strategy (dynamic), render the windowed slice, test scroll performance with the real row count, verify keyboard navigation still reaches all rows, then confirm memory stays flat while scrolling.", "k": ["Render visible rows only — recycle DOM nodes.", "Fixed heights simple; dynamic heights need measurement.", "Scroll performance tested with real row counts.", "Keyboard nav must still reach every row."], "r": ["A virtualization library.", "Realistic row count for testing.", "Row height strategy."], "s": ["Memory stays flat during long scrolls.", "All rows reachable by keyboard and screen reader."], "c": ["react-window — react-window.vercel.app", "TanStack virtual — tanstack.com/virtual"], "sig": "Signature rule: Signature virtual lists include a non-virtualized fallback for print — printed pages show all rows.", "demo": "// windowing math: which rows are visible?\nfunction visibleRows(scrollTop, viewportH, rowH, total){\n  const start=Math.max(0,Math.floor(scrollTop/rowH)-2);\n  const end=Math.min(total,Math.ceil((scrollTop+viewportH)/rowH)+2);\n  return {start,end,count:end-start};\n}\nconsole.log(visibleRows(5000,600,40,100000));\nconsole.log('100k rows -> ~20 DOM nodes mounted');"}, {"t": "Form Components That Don't Hurt", "cat": "components", "d": "Good form components: controlled inputs with a single state source, validation on blur (not on every keystroke), errors announced via aria-describedby, and submission disabled while invalid or submitting. Build primitives — TextField, Select, Checkbox, RadioGroup — that pair label+input+error automatically. Uncontrolled with refs is fine for huge forms, but controlled is easier to reason about. AI-generated forms most often fail on error association: the error text must be programmatically linked to the input or screen readers miss it.", "h": "Build TextField pairing label, input, and error with aria-describedby; validate on blur and on submit; disable submit while submitting; test the full flow with keyboard only and a screen reader; then extract the pattern into shared primitives.", "k": ["Validate on blur/submit — not every keystroke.", "Errors linked via aria-describedby.", "Submit disabled while invalid or in-flight.", "Label+input+error ship as one primitive."], "r": ["A form state approach (controlled or library).", "A validation function or schema.", "Screen reader for testing."], "s": ["Every input has an associated label.", "Errors announced to assistive tech."], "c": ["WAI-ARIA form patterns — w3.org/WAI/ARIA/apg/patterns", "React Hook Form — react-hook-form.com"], "sig": "Signature rule: Signature forms preserve user input across validation failures and navigation — typed data is never lost silently.", "demo": "// field primitive logic\nfunction fieldState(value, validate){\n  const errors=validate(value);\n  return {value, errors, describedBy: errors.length?'err-'+Math.random().toString(36).slice(2,7):undefined};\n}\nconst f=fieldState('',v=>v.trim()?[]:['Name is required']);\nconsole.log('errors:',f.errors,'aria link:',f.describedBy);"}, {"t": "Global State with a Tiny Store", "cat": "state-management", "d": "A tiny global store (zustand, nanostores, or 40 lines of pub/sub) holds cross-cutting state: auth user, theme, toasts, feature flags. Keep it minimal — most state belongs in components or the server cache. The store shape that works: state object, actions that set it, selectors for subscriptions so components re-render only on their slice. AI apps overuse global state; the discipline is: if two distant components need it and it isn't server data, it goes in the store. Everything else stays local.", "h": "Create the store with state + actions + selectors, subscribe components to slices (not the whole store), keep server data out (that's the server cache's job), add a devtools/reset hook, then verify a state change re-renders only subscribed components.", "k": ["Store holds cross-cutting UI state, not server data.", "Selectors prevent whole-app re-renders.", "Actions are the only writers — no direct mutation.", "Resettable for tests and logout."], "r": ["A store library or 40-line pub/sub.", "Selector-based subscriptions.", "A reset function."], "s": ["No component reads the entire store blindly.", "State serializable for debugging."], "c": ["Zustand docs — docs.pmnd.rs/zustand", "State management guide — react.dev/learn/managing-state"], "sig": "Signature rule: Signature stores log every action in dev with before/after — state changes are always traceable.", "demo": "// 40-line store\nfunction createStore(initial){\n  let s=initial; const subs=new Set();\n  return {\n    get(){return s;},\n    set(patch){s={...s,...patch}; subs.forEach(f=>f(s));},\n    subscribe(f){subs.add(f); return ()=>subs.delete(f);}\n  };\n}\nconst store=createStore({theme:'light',user:null});\nstore.subscribe(s=>console.log('theme ->',s.theme));\nstore.set({theme:'dark'});\nconsole.log('user untouched:',store.get().user);"}, {"t": "Server State vs Client State", "cat": "state-management", "d": "Server state (fetched data) and client state (UI state) need different tools: server state goes in a data-fetching library (TanStack Query, SWR) with caching, deduping, retries, and invalidation; client state stays in components or the tiny store. Mixing them — stuffing API responses into a global store by hand — recreates caching bugs the libraries already solved. The rule: if it came from the network, the query library owns it; the UI derives from it.", "h": "Move all fetches into query hooks with keys, configure staleTime and retries, derive UI state locally from query data, implement mutations with optimistic updates and rollback, then delete the hand-rolled fetch+store code and watch the bug class disappear.", "k": ["Network data belongs to the query library, not a hand store.", "Query keys are the cache identity — design them well.", "Mutations: optimistic update, then confirm or rollback.", "Derive UI state; don't duplicate server data locally."], "r": ["TanStack Query or SWR.", "Query key conventions.", "An API to fetch from."], "s": ["No hand-rolled caching of API responses.", "Loading and error states handled per query."], "c": ["TanStack Query docs — tanstack.com/query", "SWR docs — swr.vercel.app"], "sig": "Signature rule: Signature query keys include the data version — a backend schema change invalidates caches by construction.", "demo": "// query-key design\nfunction key(resource, params){return [resource, JSON.stringify(params||{})];}\nconsole.log(key('users',{page:2}));\nconsole.log(key('users',{page:2}));\nconsole.log('same key -> cache hit; different params -> different key');\n// invalidation: after mutating user 7, invalidate ['users', ...] keys"}, {"t": "URL as State", "cat": "state-management", "d": "The URL is the best state store for shareable UI state: filters, sort, page, selected tab, search query. Put it in query params (?q=shoes&sort=price&page=2) so links share exactly what the user sees — back button works, refresh works, support can reproduce. Keep ephemeral UI state (dropdown open, hover) out of the URL. Sync with the router's query API, debounce rapid changes (typing), and validate params on load (bad values fall back to defaults, never crash).", "h": "Identify shareable state (filters, pagination, tabs), sync it to query params via the router, add validation with safe defaults on load, debounce text inputs, then test: copy URL to a new tab and confirm identical view; hit back and confirm state restores.", "k": ["Shareable state lives in the URL — links reproduce views.", "Ephemeral UI state stays out of the URL.", "Validate params on load; bad values get defaults.", "Debounce rapid param updates (search typing)."], "r": ["A router with query param support.", "Param validation with defaults.", "Debounce utility."], "s": ["Pasted URLs always render a valid view.", "Back/forward navigates state correctly."], "c": ["URL design — developer.mozilla.org/en-US/docs/Web/API/URLSearchParams", "Next.js routing — nextjs.org/docs/app/building-your-application/routing"], "sig": "Signature rule: Signature URL state is versioned (?v=2) — old shared links migrate instead of breaking.", "demo": "// URL state sync sketch\nfunction readState(url){\n  const p=new URL(url).searchParams;\n  const page=Math.max(1,parseInt(p.get('page')||'1',10)||1);\n  return {q:p.get('q')||'', sort:['price','name'].includes(p.get('sort'))?p.get('sort'):'name', page};\n}\nconsole.log(readState('https://acme.com/shop?q=shoes&sort=bogus&page=-3'));\nconsole.log('bad values fell back to defaults, never crashed');"}, {"t": "Optimistic UI Updates", "cat": "state-management", "d": "Optimistic UI applies the change instantly and reconciles with the server after: liking a post, toggling a todo, sending a chat message. The pattern: snapshot current state, apply locally, fire the mutation, on success confirm, on failure rollback to the snapshot and show the error. It makes apps feel instant. The discipline: only optimistically apply changes you can cleanly undo, and always handle the failure path — silent divergence between UI and server is worse than a spinner.", "h": "Pick a mutation (toggle/like), implement snapshot→apply→reconcile with rollback, simulate a server failure to verify rollback restores exact prior state, add a subtle 'syncing' indicator for the in-flight window, then test rapid repeated toggles for race safety.", "k": ["Snapshot before applying — rollback needs the exact prior state.", "Failure always rolls back AND shows the error.", "Only optimistically apply cleanly-undoable changes.", "Rapid actions need idempotency or sequencing."], "r": ["A mutation API.", "Client state to snapshot.", "A way to simulate failures."], "s": ["UI never diverges silently from server truth.", "In-flight state visible to the user."], "c": ["Optimistic UI — tanstack.com/query/docs/guides/optimistic-updates", "Apollo optimistic — apollographql.com/docs/react/performance/optimistic-ui"], "sig": "Signature rule: Signature optimistic updates carry a client mutation ID — retries never double-apply.", "demo": "// optimistic toggle with rollback\nlet server={liked:false}; let ui={liked:false};\nasync function toggleLike(fail){\n  const snap=ui.liked; ui.liked=!ui.liked; console.log('ui instantly:',ui.liked);\n  await new Promise(r=>setTimeout(r,50));\n  if(fail){ui.liked=snap; console.log('server failed -> rolled back to',ui.liked);}\n  else{server.liked=ui.liked; console.log('server confirmed:',server.liked);}\n}\n(async()=>{await toggleLike(false); await toggleLike(true);})();"}, {"t": "Undo/Redo with Command Stack", "cat": "state-management", "d": "Undo/redo is a command stack: every mutation is a command object with do() and undo(), pushed onto history; undo pops and reverses, redo re-applies. Works for editors, drawing tools, form builders — anywhere users edit. Commands must be invertible (store old values), coalesced (typing merges into one command per pause), and bounded (cap history at e.g. 100). AI editing tools need this desperately — generated edits without undo feel dangerous.", "h": "Model mutations as {do, undo} commands, push onto a history stack with a cap, coalesce rapid typing commands, wire Ctrl+Z / Ctrl+Shift+Z, then test: perform 5 edits, undo 3, redo 2, and verify exact state at each step.", "k": ["Mutations are invertible commands, not raw state sets.", "Coalesce rapid edits (typing) into single commands.", "Cap history — unbounded stacks leak memory.", "Keyboard shortcuts are expected: Ctrl+Z / Ctrl+Shift+Z."], "r": ["A command abstraction.", "A history stack with cap.", "Keyboard shortcut handling."], "s": ["Undo restores exact prior state, byte for byte.", "History cap prevents memory growth."], "c": ["Command pattern — refactoring.guru/design-patterns/command", "Undo in web apps — web.dev patterns"], "sig": "Signature rule: Signature undo stacks persist across reloads for documents — closing the tab doesn't lose the ability to undo.", "demo": "function history(limit=100){\n  const done=[],undone=[];\n  return {\n    exec(cmd){cmd.do(); done.push(cmd); if(done.length>limit)done.shift(); undone.length=0;},\n    undo(){const c=done.pop(); if(c){c.undo(); undone.push(c);}},\n    redo(){const c=undone.pop(); if(c){c.do(); done.push(c);}}\n  };\n}\nlet text='';\nconst h=history();\nconst type=(s)=>({do:()=>text+=s, undo:()=>text=text.slice(0,-s.length)});\nh.exec(type('hello')); h.exec(type(' world'));\nh.undo(); console.log('after undo:',JSON.stringify(text));\nh.redo(); console.log('after redo:',JSON.stringify(text));"}, {"t": "State Machines for Complex UI", "cat": "state-management", "d": "Complex UI (wizards, players, editors, checkout flows) should be a state machine: explicit states, explicit transitions, impossible states unrepresentable. XState (or a 60-line machine) replaces boolean soup (isLoading && !hasError && isOpen) with states like idle/loading/success/error and guarded transitions. The payoff: the UI can't be in a contradictory state, transitions are logged, and the machine can be visualized and tested exhaustively. AI-generated multi-step flows become reliable instead of hopefully-correct.", "h": "List the real states of the flow, define allowed transitions (and guards), implement with XState or a tiny machine, render UI purely from current state, then test every transition including invalid ones (they must be rejected, not crash).", "k": ["Explicit states beat boolean soup.", "Impossible states become unrepresentable.", "Transitions logged — debugging a flow means reading the log.", "Machines are visualizable and exhaustively testable."], "r": ["XState or a tiny machine implementation.", "A flow with 3+ real states.", "Transition tests."], "s": ["No contradictory UI states reachable.", "Invalid transitions rejected safely."], "c": ["XState docs — xstate.js.org", "Statecharts — statecharts.dev"], "sig": "Signature rule: Signature machines export their diagram as docs — the state chart is generated from the code, never drawn separately.", "demo": "// tiny state machine\nfunction machine(def, initial){\n  let s=initial;\n  return {\n    get state(){return s;},\n    send(evt){\n      const next=def[s]&&def[s][evt];\n      if(!next){console.log(`rejected: ${s} + ${evt}`); return false;}\n      console.log(`${s} --${evt}--> ${next}`); s=next; return true;\n    }\n  };\n}\nconst m=machine({idle:{FETCH:'loading'},loading:{OK:'done',FAIL:'error'},error:{RETRY:'loading'},done:{}},'idle');\nm.send('FETCH'); m.send('OK'); m.send('FETCH'); // rejected: done has no FETCH"}, {"t": "Derived State and Selectors", "cat": "state-management", "d": "Derived state is computed from source state with memoized selectors: filtered lists, totals, permissions — never stored separately, or the copies drift. Use memoized selectors (reselect, or useMemo) so derivation runs only when inputs change. The rule is single source of truth: raw state lives in one place, everything else derives. AI code often stores derived values and then forgets to update them; selectors make staleness structurally impossible.", "h": "Identify every stored value that's computable from other state, replace with memoized selectors, verify recomputation only fires on input change (log it), write a test mutating source state and asserting derived values update, then delete the duplicated stored copies.", "k": ["Single source of truth — derive, don't duplicate.", "Memoize expensive derivations.", "Selectors are the API to state, not raw reads.", "Staleness becomes structurally impossible."], "r": ["A memoization mechanism.", "Clear source-vs-derived inventory.", "Tests asserting derivation freshness."], "s": ["No stored value is computable from other stored state.", "Derivations pure and testable."], "c": ["Reselect — github.com/reduxjs/reselect", "Derived state — react.dev/learn/choosing-the-state-structure"], "sig": "Signature rule: Signature selectors carry a cost label — expensive derivations are flagged in code review automatically.", "demo": "// memoized selector\nfunction memoize(fn){\n  let lastArgs,lastVal;\n  return (...a)=>{\n    if(lastArgs&&a.length===lastArgs.length&&a.every((x,i)=>x===lastArgs[i]))return lastVal;\n    lastArgs=a; lastVal=fn(...a); console.log('(recomputed)'); return lastVal;\n  };\n}\nconst total=memoize(items=>items.reduce((s,i)=>s+i.price,0));\nconst cart=[{price:10},{price:20}];\nconsole.log(total(cart)); console.log(total(cart)); // cached\nconsole.log(total([...cart,{price:5}])); // recomputed"}, {"t": "CSS Architecture: From Chaos to System", "cat": "styling-systems", "d": "CSS architecture is naming and scoping discipline: BEM naming, CSS Modules (local scope by default), or utility-first (Tailwind). Pick one and enforce it — mixed approaches in one codebase is the actual chaos. CSS Modules suit component teams (styles live with components, collisions impossible); Tailwind suits speed (design in markup, consistent scale). Either way: design tokens (colors, spacing, type scale) as CSS variables are the foundation. AI-generated UIs need tokens most — without them, every AI invents slightly different grays.", "h": "Choose one methodology, define design tokens as CSS variables, set up the scoping mechanism (modules or utilities), convert one messy page as the reference example, lint for methodology violations, then document the 'which approach when' rule.", "k": ["One methodology per codebase — mixing is the chaos.", "Design tokens first: colors, spacing, type as variables.", "Scoping (modules) or constraints (utilities) prevent collisions.", "AI output needs tokens or every gray differs."], "r": ["A chosen methodology.", "Design tokens defined.", "A linter or convention check."], "s": ["No global class collisions.", "Token values the single source of visual truth."], "c": ["BEM — getbem.com", "Tailwind docs — tailwindcss.com/docs", "CSS modules — github.com/css-modules/css-modules"], "sig": "Signature rule: Signature stylesheets forbid raw hex outside the tokens file — colors come from tokens or they don't ship.", "demo": ":root{\n  --color-ink:#1a1a2e;\n  --color-paper:#ffffff;\n  --space-1:4px; --space-2:8px; --space-4:16px;\n  --radius:8px;\n}\n.card{\n  background:var(--color-paper);\n  color:var(--color-ink);\n  padding:var(--space-4);\n  border-radius:var(--radius);\n}\nconsole.log('tokens defined; components consume variables, never raw values');"}, {"t": "Design Tokens in Practice", "cat": "styling-systems", "d": "Design tokens are named decisions: color.brand.500, space.4, font.heading — stored as JSON/YAML and transformed to CSS variables, iOS, Android formats (Style Dictionary). Tokens separate decision from implementation: rebrand by changing tokens, not components. Tier them: base (raw values) → semantic (brand.primary, text.muted) → component (button.bg). AI theming (dark mode, white-label) becomes a token swap instead of a rewrite.", "h": "Define base tokens (raw palette), semantic tokens (meaning-mapped), component tokens; set up Style Dictionary (or hand-rolled transform) to emit CSS variables; build dark mode as a token override; then rebrand the app by editing only tokens.", "k": ["Three tiers: base → semantic → component.", "Tokens as data (JSON), transformed to each platform.", "Dark mode = token override, not a rewrite.", "Rebrand by editing tokens only."], "r": ["A token source file.", "A transform to CSS variables.", "A dark-mode override set."], "s": ["No raw values in components — tokens only.", "Token changes propagate to all platforms."], "c": ["Style Dictionary — amzn.github.io/style-dictionary", "Design tokens — designtokens.org"], "sig": "Signature rule: Signature token files include contrast ratios per pair — accessibility is computed, not eyeballed.", "demo": "// tokens as data -> CSS variables\nconst tokens={\n  color:{brand:{500:'#2f7bff'},ink:'#1a1a2e'},\n  space:{4:'16px'}\n};\nfunction toCSS(t,prefix=''){\n  let out='';\n  for(const [k,v] of Object.entries(t)){\n    const name=prefix?prefix+'-'+k:k;\n    out+= typeof v==='object' ? toCSS(v,name) : `  --${name}: ${v};\\n`;\n  }\n  return out;\n}\nconsole.log(':root{\\n'+toCSS(tokens)+' }');"}, {"t": "Responsive Design Without Breakpoint Soup", "cat": "styling-systems", "d": "Responsive without soup: mobile-first CSS (base styles are mobile; min-width queries add complexity upward), a small set of breakpoints tied to content (not devices), fluid type with clamp(), and container queries for component-level responsiveness. Breakpoint soup happens when every component invents its own breakpoints — fix with 3-4 shared tokens. AI layouts should default to fluid grids (auto-fit, minmax) that adapt without any breakpoints at all.", "h": "Set 3-4 shared breakpoint tokens, write mobile-first (min-width only), use clamp() for fluid type, prefer auto-fit/minmax grids that need no breakpoints, add container queries where components need self-awareness, then test at 360px, 768px, 1440px.", "k": ["Mobile-first: base is mobile, queries add up.", "Breakpoints tied to content, shared as tokens.", "clamp() for fluid type — no breakpoint for every size.", "Grids with auto-fit/minmax adapt breakpoint-free."], "r": ["Shared breakpoint tokens.", "A fluid type scale.", "Test viewports (360/768/1440)."], "s": ["No horizontal scroll at any width.", "Touch targets ≥44px on mobile."], "c": ["Responsive design — web.dev/responsive", "Container queries — developer.mozilla.org/en-US/docs/Web/CSS/CSS_container_queries"], "sig": "Signature rule: Signature CSS bans max-width queries for layout — mobile-first min-width only, keeping the cascade predictable.", "demo": "/* fluid, breakpoint-free card grid */\n.grid{\n  display:grid;\n  grid-template-columns:repeat(auto-fit,minmax(240px,1fr));\n  gap:var(--space-4);\n}\n.fluid-type{font-size:clamp(1rem,2.5vw,1.5rem);}\nconsole.log('grid adapts 1->N columns with zero media queries');"}, {"t": "Dark Mode Done Right", "cat": "styling-systems", "d": "Dark mode done right: token-driven (a [data-theme=dark] override block re-maps semantic tokens), respects prefers-color-scheme by default, persists user choice in localStorage, avoids pure black/white (use dark grays), and transitions colors smoothly. Images need dimming rules; shadows become glows. The failure mode is hardcoded colors scattered through components — with tokens, dark mode is ~30 lines. AI-generated themes should always ship both modes from the token set.", "h": "Build the light token set, add the dark override block, wire the theme toggle (system default → stored preference), audit for hardcoded colors, dim images appropriately, then test contrast ratios in both modes.", "k": ["Tokens make dark mode a ~30-line override.", "System preference default; stored choice wins.", "Avoid pure #000/#fff — dark grays are easier on eyes.", "Contrast checked in BOTH modes."], "r": ["Semantic color tokens.", "A theme toggle + persistence.", "Contrast checker."], "s": ["WCAG contrast passes in both themes.", "No flash of wrong theme on load."], "c": ["Dark mode — web.dev/color-scheme", "prefers-color-scheme — developer.mozilla.org"], "sig": "Signature rule: Signature themes set color-scheme: light dark — native form controls follow the theme automatically.", "demo": "/* dark mode = token remap */\n:root{--bg:#ffffff;--ink:#1a1a2e;color-scheme:light;}\n[data-theme=\"dark\"]{--bg:#12121c;--ink:#e8e8f2;color-scheme:dark;}\nbody{background:var(--bg);color:var(--ink);transition:background .2s,color .2s;}\nconsole.log('theme toggle: set data-theme on <html>, persist choice, default to matchMedia');"}, {"t": "Animations That Respect Users", "cat": "styling-systems", "d": "Good animations: transform/opacity only (GPU-cheap, no layout thrash), 200-300ms durations, ease-out curves, and prefers-reduced-motion respected (disable non-essential motion). Animate state changes (enter/exit, expand, tab switches) — not decoration. FLIP technique animates layout changes smoothly. AI-generated UIs often over-animate; the rule is motion with purpose: it orients the user (where did that come from?) or it doesn't ship.", "h": "Define motion tokens (durations, easings), animate only transform/opacity, add the reduced-motion media query disabling non-essential animation, use FLIP for list reorder, then test with reduced-motion enabled and on a low-end device.", "k": ["transform/opacity only — layout animations jank.", "200-300ms, ease-out — the standard feel.", "prefers-reduced-motion disables non-essential motion.", "Motion orients the user or it doesn't ship."], "r": ["Motion tokens.", "A reduced-motion test setup.", "A low-end device or throttled CPU test."], "s": ["All motion disabled under prefers-reduced-motion.", "No animation blocks interaction."], "c": ["Animations guide — web.dev/animations", "prefers-reduced-motion — developer.mozilla.org"], "sig": "Signature rule: Signature motion tokens cap durations — no animation over 500ms without an explicit override comment.", "demo": "/* respectful animation */\n.fade-in{animation:fade .25s ease-out;}\n@keyframes fade{from{opacity:0;transform:translateY(8px);}to{opacity:1;transform:none;}}\n@media (prefers-reduced-motion:reduce){\n  .fade-in{animation:none;}\n  *{transition-duration:0.01ms !important;}\n}\nconsole.log('motion: transform/opacity, 250ms, reduced-motion respected');"}, {"t": "CSS Containment and Isolation", "cat": "styling-systems", "d": "CSS containment (contain: layout/style/paint) tells the browser a subtree is independent — layout inside can't affect outside, so the browser skips work. content-visibility: auto skips rendering off-screen content entirely (huge for long pages). Shadow DOM gives true style isolation for embeddable widgets. Use containment on independent widgets, content-visibility on below-fold sections, shadow DOM when shipping components to other people's pages. AI-generated embeddable widgets (chat bubbles, badges) need shadow DOM or host-page CSS will break them.", "h": "Add contain: content to independent widgets, content-visibility: auto with intrinsic-size to long lists, use shadow DOM for embeddable components, measure rendering performance before/after, then verify host pages can't leak styles into shadow components.", "k": ["contain: tells the browser what's independent.", "content-visibility: auto skips off-screen rendering.", "Shadow DOM = true style isolation for embeds.", "Measure — containment is a performance tool."], "r": ["A performance measurement setup.", "Long content to test with.", "An embed scenario for shadow DOM."], "s": ["No visual regressions from containment.", "Embeds immune to host-page styles."], "c": ["CSS containment — developer.mozilla.org/en-US/docs/Web/CSS/contain", "content-visibility — web.dev/content-visibility"], "sig": "Signature rule: Signature embeds always use shadow DOM — a widget that breaks on чужой CSS is a bug report waiting.", "demo": "// shadow DOM embed sketch\nconst host=document.createElement('div');\nconst shadow=host.attachShadow?host.attachShadow({mode:'open'}):null;\nconsole.log('shadow root:',!!shadow,'-> host page CSS cannot reach inside');\nconsole.log('widget styles fully isolated; use for chat bubbles, badges, embeds');"}, {"t": "File-Based Routing Fundamentals", "cat": "routing", "d": "File-based routing (Next.js, Nuxt, SvelteKit, Astro): files in the routes/pages directory ARE the URLs — index.tsx → /, about.tsx → /about, blog/[slug].tsx → /blog/:slug. Conventions cover layouts (shared chrome), loading states, error boundaries per route, and API routes alongside pages. The win is zero routing config — the filesystem is the source of truth, and AI file generation automatically creates correct routes. Learn the framework's special files (layout, loading, error, not-found) — they're the whole mental model.", "h": "Create the routes directory structure, add a root layout, per-route loading and error files, a dynamic [slug] route, verify each URL resolves, then add a nested layout and confirm it composes without touching the router config.", "k": ["Filesystem is the router — no config to drift.", "Special files (layout/loading/error) are the mental model.", "Dynamic segments with [brackets].", "Layouts nest by directory structure."], "r": ["A file-based routing framework.", "Conventions doc for special files.", "A nested route to test composition."], "s": ["Every route has loading and error states.", "Unknown URLs hit the not-found route."], "c": ["Next.js routing — nextjs.org/docs/app/building-your-application/routing", "SvelteKit routing — kit.svelte.dev/docs/routing"], "sig": "Signature rule: Signature route trees generate a sitemap from the filesystem — routes and sitemap can't disagree.", "demo": "// file tree -> routes\nconst files=['app/page.tsx','app/about/page.tsx','app/blog/[slug]/page.tsx','app/blog/layout.tsx'];\nfunction route(f){return '/'+f.replace('app/','').replace('/page.tsx','').replace('page.tsx','').replace('[slug]',':slug').replace(/\\/$/,'')||'/';}\nfiles.forEach(f=>console.log(f,'->',route(f)||'/'));"}, {"t": "Client-Side Router from Scratch", "cat": "routing", "d": "A minimal client router is ~50 lines: listen for link clicks (intercept same-origin), pushState the URL, match against route patterns, render the matched component, handle back/forward via popstate, scroll to top on navigation. Building one teaches what frameworks abstract: history management, route matching with params, and lazy loading per route. AI single-page tools without a framework (or with a tiny one) use exactly this — understanding it makes framework routers trivial.", "h": "Write the router (intercept clicks, pushState, match patterns, render), add popstate handling for back/forward, implement per-route lazy loading, add scroll restoration, then test deep links, back button, and unknown routes.", "k": ["pushState + popstate is the whole mechanism.", "Intercept same-origin clicks; let the rest be real links.", "Route patterns extract params.", "Lazy-load route components for speed."], "r": ["History API knowledge.", "Route pattern matcher.", "Lazy import mechanism."], "s": ["Back/forward works like a real site.", "Unknown routes show not-found, not blank."], "c": ["History API — developer.mozilla.org/en-US/docs/Web/API/History_API", "SPA routing patterns — web.dev"], "sig": "Signature rule: Signature routers prefetch the next likely route on link hover — navigation feels instant.", "demo": "// 50-line router sketch\nconst routes=[];\nfunction route(pattern, render){routes.push({re:new RegExp('^'+pattern.replace(/:\\w+/g,'([^/]+)')+'$'),render});}\nfunction navigate(path){\n  history.pushState({},'',path);\n  const [clean]=path.split('?');\n  for(const r of routes){const m=clean.match(r.re); if(m){r.render(m.slice(1)); return;}}\n  console.log('404:',path);\n}\nroute('/','()=>{}'); route('/user/:id',(p)=>console.log('user page, id='+p[0]));\nnavigate('/user/42'); navigate('/nope');"}, {"t": "Nested Layouts and Outlets", "cat": "routing", "d": "Nested layouts let routes share chrome: the dashboard layout (sidebar + header) wraps all /dashboard/* pages; each page renders into the layout's outlet. The layout persists across page changes (no re-mount, state survives), while the outlet swaps. This composes: root layout → dashboard layout → settings layout → page. AI-generated admin tools and multi-section sites need this — without it, every page rebuilds the sidebar and navigation state resets on each click.", "h": "Define the root layout with an outlet, nest a section layout inside it, verify the layout doesn't remount on page change (log it), keep layout-level state (collapsed sidebar) across navigations, then add a third nesting level to prove composition.", "k": ["Layouts persist; outlets swap.", "Layout state (sidebar) survives navigation.", "Nesting composes: root → section → page.", "No layout = every page rebuilds shared chrome."], "r": ["A router with outlet support.", "Layout components.", "A remount-detection log."], "s": ["Layouts never remount on child navigation.", "Deep links render the full layout chain."], "c": ["Nested routes — reactrouter.com/en/main/start/concepts#nested-routes", "Next.js layouts — nextjs.org/docs/app/building-your-application/routing/pages-and-layouts"], "sig": "Signature rule: Signature layouts declare their data needs — parent layouts fetch before children render, no waterfalls.", "demo": "// nested layout composition\nfunction Root(inner){return `<div class=root><header>Acme</header>${inner}</div>`;}\nfunction Dash(inner){return `<div class=dash><nav>sidebar</nav><main>${inner}</main></div>`;}\nfunction Page(){return `<h1>Settings</h1>`;}\nconsole.log(Root(Dash(Page())));\nconsole.log('layouts wrap; only Page() swaps on navigation')"}, {"t": "Route Guards and Auth", "cat": "routing", "d": "Route guards decide who sees what: public routes, authenticated routes (redirect to login with return-to), and role routes (admin-only). Implement as wrappers or middleware that check auth state BEFORE rendering — never render-then-hide (content flashes and data may leak via props). Store the intended URL so login returns the user where they were headed. AI-generated apps must get this right: the check happens on the route, and the API enforces it independently — client guards are UX, server checks are security.", "h": "Create guard components (RequireAuth, RequireRole), redirect unauthenticated users to login with ?next=, verify no protected content flashes before redirect, test role escalation attempts, and confirm the API rejects unauthorized calls regardless of the client guard.", "k": ["Check BEFORE render — never render-then-hide.", "Remember ?next= so login returns correctly.", "Client guards are UX; the API enforces security.", "Role checks on every privileged route."], "r": ["An auth state source.", "Login route.", "API-side authorization."], "s": ["No protected content flashes for unauthorized users.", "Direct URL access to guarded routes redirects."], "c": ["Auth patterns — owasp.org/www-project-authentication-cheat-sheet", "Next.js middleware — nextjs.org/docs/app/building-your-application/routing/middleware"], "sig": "Signature rule: Signature guards log denied accesses — repeated denials trigger a review, not just a redirect.", "demo": "// guard logic\nconst session={user:{name:'Ada',role:'editor'}};\nfunction guard(route){\n  if(route.auth&&!session.user)return {redirect:'/login?next='+route.path};\n  if(route.role&&session.user?.role!==route.role)return {redirect:'/denied'};\n  return {render:true};\n}\nconsole.log(guard({path:'/admin',auth:true,role:'admin'}));\nconsole.log(guard({path:'/docs',auth:true}));"}, {"t": "Code Splitting per Route", "cat": "routing", "d": "Code splitting per route means each page loads only its own JavaScript: the router lazy-loads route components (import()), the bundler emits one chunk per route, and navigation fetches the chunk on demand. Initial load drops dramatically — users download the homepage, not the admin panel. Add prefetching on link hover/viewport for instant-feeling navigation, and a loading fallback per route. AI-generated sites get this free from file-based routers; hand routers must wire import() themselves.", "h": "Convert route components to lazy imports, verify the bundler emits per-route chunks, measure initial JS before/after, add hover-prefetch on links, then throttle the network and confirm navigation still feels fast.", "k": ["One chunk per route — initial load stays small.", "Lazy import() is the mechanism.", "Prefetch on hover/viewport for instant nav.", "Loading fallback per route, not a global spinner."], "r": ["A bundler with dynamic import support.", "Route-level lazy() wrappers.", "Network throttling for testing."], "s": ["Initial JS budget met.", "No route loads another route's code eagerly."], "c": ["Code splitting — web.dev/reduce-javascript-payloads", "React lazy — react.dev/reference/react/lazy"], "sig": "Signature rule: Signature builds fail if any route chunk duplicates a shared dependency — shared code belongs in the shared chunk.", "demo": "// route-level splitting sketch\nconst loadHome=()=>import('./routes/home.js');\nconst loadAdmin=()=>import('./routes/admin.js');\nconsole.log('home chunk: only home code');\nconsole.log('admin chunk loads on first /admin visit, prefetched on hover');\nconsole.log('bundler emits home.[hash].js, admin.[hash].js automatically');"}, {"t": "Core Web Vitals in Practice", "cat": "performance", "d": "Core Web Vitals are Google's user-experience metrics and a ranking factor: LCP (largest contentful paint <2.5s), INP (interaction to next paint <200ms), CLS (cumulative layout shift <0.1). Fix LCP with server rendering or static generation plus image priority; fix INP by breaking up long tasks and debouncing handlers; fix CLS by reserving space for images/ads (width/height attributes). Measure with real-user data (CrUX) and lab (Lighthouse). AI-generated pages commonly fail CLS — images without dimensions shift the layout.", "h": "Measure the three vitals on key pages, fix the worst offender (usually LCP via image priority or INP via task chunking), add width/height to all images to kill CLS, set up real-user monitoring, then re-measure and record the before/after.", "k": ["LCP <2.5s, INP <200ms, CLS <0.1 — the targets.", "Images need dimensions — CLS's #1 cause.", "Break up long tasks for INP.", "Real-user data (CrUX) beats lab-only testing."], "r": ["Lighthouse / PageSpeed Insights.", "Real-user monitoring.", "Image dimension discipline."], "s": ["Vitals green on key pages for real users.", "No layout shift from images or ads."], "c": ["Web Vitals — web.dev/vitals", "Optimize LCP — web.dev/optimize-lcp"], "sig": "Signature rule: Signature pages budget each vital in CI — a PR that regresses LCP past the budget fails.", "demo": "node -e \"\nconst vitals={LCP:2.1,INP:150,CLS:0.05};\nconst budget={LCP:2.5,INP:200,CLS:0.1};\nfor(const k of Object.keys(vitals)){\n  const ok=vitals[k]<=budget[k];\n  console.log(k, vitals[k], ok?'PASS':'FAIL');\n}\""}, {"t": "Image Optimization Pipeline", "cat": "performance", "d": "Images are usually the biggest bytes on a page: serve modern formats (AVIF/WebP with fallbacks), responsive sizes (srcset), lazy-load below the fold (loading=lazy), priority-load the hero (fetchpriority=high), and always include width/height. Automate with an image CDN or build-time optimizer (sharp, next/image) so no human resizes by hand. AI-generated sites with unoptimized PNGs are the classic performance disaster — the pipeline makes optimization automatic.", "h": "Set up build-time or CDN image optimization, convert hero images to AVIF/WebP with fallbacks, add srcset sizes, lazy-load below-fold images, prioritize the LCP image, then compare page weight before/after.", "k": ["Modern formats (AVIF/WebP) with fallbacks.", "srcset serves the right size per device.", "loading=lazy below fold; hero gets priority.", "Dimensions always — no layout shift."], "r": ["An optimizer (sharp / next/image / image CDN).", "Responsive image markup.", "Page weight measurement."], "s": ["No image served larger than its display size.", "LCP image discovered early (preload/priority)."], "c": ["Image optimization — web.dev/fast#optimize-your-images", "next/image — nextjs.org/docs/app/api-reference/components/image"], "sig": "Signature rule: Signature builds reject images over the size budget — oversized assets fail CI with the exact savings listed.", "demo": "node -e \"\n// responsive image markup generator\nfunction img(src,alt,w,h){\n  return '<img src=\\\"'+src+'.avif\\\" srcset=\\\"'+src+'-480.avif 480w, '+src+'-800.avif 800w\\\" '+ \n    'sizes=\\\"(max-width:600px) 480px, 800px\\\" width=\\\"'+w+'\\\" height=\\\"'+h+'\\\" '+ \n    'alt=\\\"'+alt+'\\\" loading=\\\"lazy\\\">';\n}\nconsole.log(img('/hero','Acme hero',1600,900).slice(0,120)+'...');\""}, {"t": "Caching Strategy for Frontends", "cat": "performance", "d": "Frontend caching has layers: HTTP cache headers (immutable for hashed assets, short for HTML), service worker for offline/app-shell, and in-memory query caches for API data. Hashed filenames (app.a1b2c3.js) allow immutable year-long caching — deploys never break cached pages because names change. HTML stays short-cache or no-cache so updates propagate. AI-deployed frontends need this from day one or users get stuck on stale bundles after every deploy.", "h": "Configure hashed asset filenames, set immutable headers on them, short-cache HTML, add a service worker for the app shell (optional), implement a deploy-time version check that prompts refresh on new versions, then deploy twice and verify no stale-bundle issues.", "k": ["Hashed assets → immutable, cache for a year.", "HTML short-cached so updates propagate.", "Version check prompts refresh on new deploys.", "Service worker for offline where it matters."], "r": ["Header control on the host/CDN.", "Hashed build output.", "A version endpoint or build ID."], "s": ["Users never stuck on stale bundles.", "Offline behavior defined, not accidental."], "c": ["HTTP caching — web.dev/http-cache", "Service workers — web.dev/service-workers"], "sig": "Signature rule: Signature deploys include a cache-bust self-test — fetch the version endpoint twice across a deploy and diff.", "demo": "// cache header plan\nconst plan={\n  '/assets/app.a1b2c3.js':'public, max-age=31536000, immutable',\n  '/index.html':'no-cache',\n  '/api/*':'no-store'\n};\nconsole.log(JSON.stringify(plan,null,1));\nconsole.log('hashed name changes per build -> old caches never poison new deploys');"}, {"t": "Debouncing, Throttling, and Idle Work", "cat": "performance", "d": "Input handlers must not do expensive work per keystroke: debounce search (wait for pause), throttle scroll/resize (at most every N ms), and defer non-critical work to requestIdleCallback. Virtualize long lists. The pattern is: user intent → cheap immediate feedback → debounced expensive work. AI-generated search boxes that query per keystroke hammer backends; a 200ms debounce plus request cancellation (AbortController) fixes it completely.", "h": "Debounce text search (250ms) with AbortController cancelling stale requests, throttle scroll handlers (100ms) or use IntersectionObserver instead, move analytics and prefetch to requestIdleCallback, then type rapidly and verify only one request fires per pause.", "k": ["Debounce completion (search); throttle rate (scroll).", "AbortController cancels stale requests.", "requestIdleCallback for non-critical work.", "IntersectionObserver beats scroll handlers."], "r": ["Debounce/throttle utilities.", "AbortController usage.", "An idle-callback fallback."], "s": ["No request per keystroke.", "Stale responses never overwrite fresh ones."], "c": ["Debounce/throttle — web.dev", "AbortController — developer.mozilla.org/en-US/docs/Web/API/AbortController"], "sig": "Signature rule: Signature search inputs cancel in-flight requests on each keystroke — the network never does wasted work.", "demo": "function debounce(fn,ms){let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>fn(...a),ms);};}\nconst search=debounce(q=>console.log('query:',q),250);\nsearch('a');search('ab');search('abc');\nsetTimeout(()=>console.log('one request per pause, not per keystroke'),400);"}, {"t": "Bundle Diet: Keeping JS Small", "cat": "performance", "d": "Keeping JavaScript small: import only what you use (named imports, lodash-es over lodash), replace heavy deps with tiny ones (date-fns over moment), tree-shake by using ESM, drop polyfills for dead browsers (browserslist), and lazy-load everything below the fold. Audit quarterly with the bundle analyzer. The AI trap is dependency sprawl — every 'just npm install X' adds weight; the diet makes each addition a conscious trade against the budget.", "h": "Run the bundle analyzer, list the top 10 modules by size, replace or cherry-pick the heavy ones, set browserslist to drop dead polyfills, lazy-load below-fold features, set the CI budget, then verify the diet holds across three feature PRs.", "k": ["Named imports + ESM = tree-shakeable.", "Tiny alternatives beat full libraries (date-fns > moment).", "browserslist kills dead-browser polyfills.", "Lazy-load below the fold — always."], "r": ["Bundle analyzer.", "A size budget.", "Dependency audit discipline."], "s": ["Budget enforced in CI.", "No library added without a size check."], "c": ["Reduce JS payloads — web.dev/articles/reduce-javascript-payloads", "browserslist — github.com/browserslist/browserslist"], "sig": "Signature rule: Signature PRs show the bundle delta as a required check — every dependency addition is a visible, reviewed cost.", "demo": "node -e \"\nconst before=[['moment',290],['lodash',72],['app',120]];\nconst after=[['date-fns/format',18],['lodash-es/debounce',8],['app',120]];\nconst sum=a=>a.reduce((s,m)=>s+m[1],0);\nconsole.log('before:',sum(before)+'KB -> after:',sum(after)+'KB');\nconsole.log('saved:',sum(before)-sum(after)+'KB by swapping heavy deps');\""}, {"t": "Perceived Performance Tricks", "cat": "performance", "d": "Perceived performance is what users feel: skeleton screens (shimmer placeholders matching layout), optimistic UI, progressive image loading (blur-up), instant navigation feedback, and prioritizing above-fold content. A 2s load with skeletons feels faster than a 1.5s blank page. These are honest techniques — they don't fake completion, they communicate progress. AI-generated apps feel professional when loading states are designed, not when spinners are sprinkled.", "h": "Design skeleton screens matching real layouts, add blur-up for images, give instant feedback on every interaction (then reconcile), prioritize above-fold rendering, then user-test: ask which version feels faster (skeletons vs spinner).", "k": ["Skeletons matching layout beat generic spinners.", "Blur-up images feel instant.", "Instant feedback + reconcile beats waiting.", "Above-fold first — the rest can stream."], "r": ["Skeleton components.", "Blur-up image technique.", "Interaction feedback patterns."], "s": ["No blank screens during loads.", "Loading states designed, not defaulted."], "c": ["Perceived performance — web.dev/perceived-performance", "Skeleton screens — uxdesign.cc"], "sig": "Signature rule: Signature loading states include a timeout — a skeleton that never resolves becomes an error message.", "demo": "// skeleton matching layout\nfunction skeleton(){\n  return `<div class=\"skel\" aria-busy=\"true\" aria-label=\"Loading\">\n    <div class=\"skel-line\" style=\"width:60%\"></div>\n    <div class=\"skel-line\" style=\"width:90%\"></div>\n    <div class=\"skel-line\" style=\"width:75%\"></div>\n  </div>`;\n}\nconsole.log(skeleton().split('\\n')[0]);\nconsole.log('skeleton mirrors content shape; resolves to content or times out to error');"}];
function ladderTier(r){return r<=2?"Foundations":(r<=4?"Compounded":"Advanced");}
function generate(seed,opts){
  opts=opts||{};
  var n=DATA.length;
  var e=DATA[(seed-1)%n];
  var cycle=Math.floor((seed-1)/n);
  var ladder=1+Math.floor((((seed-1)%n)/7));
  var rec={
    id:PREFIX+String(seed).padStart(6,'0'),
    name:e.t,
    title:DBTITLE+': '+e.t+(cycle>0?' (variant '+cycle+')':''),
    description:SRC==='signature'?('Signature treatment: '+e.sig+' '+e.d):e.d,
    category:e.cat,
    ladder_rank:ladder,
    ladder_tier:ladderTier(ladder),
    how_it_works:e.h,
    key_points:e.k,
    requirements:e.r,
    standards:e.s,
    citations:e.c,
    src:SRC,
    src_detail:SRC_DETAIL,
    seed:seed
  };
  if(SRC==='signature'){rec.signature_treatment=e.sig;}
  rec.demo={program:e.demo};
  if(opts.category&&rec.category!==opts.category){/* category filter honored at query layer */}
  return rec;
}
function escRx(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function validate(r){
  var errs=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  if(!new RegExp('^'+escRx(PREFIX)+'\\d{6}$').test(r.id||''))errs.push('id');
  if(typeof r.title!=='string'||r.title.indexOf(DBTITLE)!==0)errs.push('title');
  if(CATS.indexOf(r.category)<0)errs.push('category');
  if(!(r.ladder_rank>=1&&r.ladder_rank<=5))errs.push('ladder_rank');
  if(['Foundations','Compounded','Advanced'].indexOf(r.ladder_tier)<0)errs.push('ladder_tier');
  if(r.src!==SRC)errs.push('src');
  if(typeof r.description!=='string'||r.description.length<200)errs.push('description');
  REQUIRED.forEach(function(k){if(r[k]===undefined||r[k]===null)errs.push('missing:'+k);});
  if(!Array.isArray(r.key_points)||r.key_points.length<3)errs.push('key_points');
  if(!r.demo||typeof r.demo.program!=='string'||!r.demo.program.length)errs.push('demo');
  return {ok:errs.length===0,errors:errs};
}
function driftCheck(rec,sample){
  var dups=(sample||[]).filter(function(x){return x&&x.title===rec.title&&x.category===rec.category;});
  return dups.length?{ok:false,errors:['duplicate title+category already in archive']}:{ok:true,errors:[]};
}
var api={generate:generate,validate:validate,driftCheck:driftCheck,slug:"ai-toolmaking-frontend-development-signature",version:"jahdb-ai-toolmaking-frontend-development-signature-1.0"};
if(typeof module!=='undefined'&&module.exports)module.exports=api;
if(typeof window!=='undefined'){
  window["jahdb_ai_toolmaking_frontend_development_signature"]=api;
  try{if(window.JAHDB&&JAHDB.registerGenerator)JAHDB.registerGenerator("ai-toolmaking-frontend-development-signature",api);}catch(e){}
}
